    for (uint8_t i = 0; i < 8; i++) { m->tof_mm[i] = sp_get_u16(p + o); o = (uint8_t)(o + 2); }
    for (uint8_t i = 0; i < 4; i++) { m->sonar_mm[i] = sp_get_u16(p + o); o = (uint8_t)(o + 2); }
